      place-items: center;
      background: #ffd447;
      border: 1px solid #000;
      color: #9e1b1b;
      font-family: "Press Start 2P", monospace;
      font-size: 9px;
      line-height: 1;
    }

    .win-controls {
      display: flex;
      gap: 2px;
    }

